// Builds a "write_offchain_config" instruction.
func NewWriteOffchainConfigInstruction(
	// Params:
	offchainConfigParam []byte,

	// Accounts:
	proposalAccount solanago.PublicKey,
	authorityAccount solanago.PublicKey,
) (solanago.Instruction, error) {
	buf__ := new(bytes.Buffer)
	enc__ := binary.NewBorshEncoder(buf__)

	// Encode the instruction discriminator.
	err := enc__.WriteBytes(Instruction_WriteOffchainConfig[:], false)
	if err != nil {
		return nil, fmt.Errorf("failed to write instruction discriminator: %w", err)
	}
	{
		// Serialize `offchainConfigParam`:
		err = enc__.Encode(offchainConfigParam)
		if err != nil {
			return nil, errors.NewField("offchainConfigParam", err)
		}
	}
	accounts__ := solanago.AccountMetaSlice{}

	// Add the accounts to the instruction.
	{
		// Account 0 "proposal": Writable, Non-signer, Required
		accounts__.Append(solanago.NewAccountMeta(proposalAccount, true, false))
		// Account 1 "authority": Read-only, Signer, Required
		accounts__.Append(solanago.NewAccountMeta(authorityAccount, false, true))
	}

	// Create the instruction.
	return solanago.NewInstruction(
		ProgramID,
		accounts__,
		buf__.Bytes(),
	), nil
}
